{
  "verdict": "request_changes",
  "summary": "Candidate violates contract by accepting equal version updates.",
  "findings": [
    {
      "finding_id": "F001",
      "file": "candidate.py",
      "line_start": 2,
      "line_end": 4,
      "severity": "high",
      "description": "The function incorrectly accepts updates when the provided version is equal to the current state version. The specification requires that updates are applied only when the new version is strictly greater than the current version.",
      "evidence": "Calling advance(state, 2, 'x') on state={'version': 2, 'value': 'a', 'writes': 0} returns True and increments writes to 1, updating the state, which contradicts the contract that equal or older versions should return False and leave the state unchanged."
    }
  ]
}
